import { useState, useEffect, useRef } from "react";
import "./Home.css";
import "@fontsource-variable/roboto"; 

export default function Window({
  title,
  children,
  onClose,
  initialPosition,
  onFocus,
  zIndex = 5,
  width = 800,
  playClick,
  soundOn
}) {
  const [position, setPosition] = useState(initialPosition);
  const [phase, setPhase] = useState("entering"); // entering → idle → closing
  const dragging = useRef(false);
  const offset = useRef({ x: 0, y: 0 });

  useEffect(() => {
    const t = setTimeout(() => setPhase("idle"), 350); // after animation in
    return () => clearTimeout(t);
  }, []);

  const startDrag = (e) => {
    if (e.button !== 0 || e.target.closest("[data-no-drag]")) return;
    dragging.current = true;
    onFocus?.();
    const rect = e.currentTarget.parentElement.getBoundingClientRect();
    offset.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    e.currentTarget.setPointerCapture?.(e.pointerId);
  };

  const onMove = (e) => {
    if (!dragging.current) return;
    setPosition({ x: e.clientX - offset.current.x, y: e.clientY - offset.current.y });
  };

  const endDrag = (e) => {
    dragging.current = false;
    e.currentTarget.releasePointerCapture?.(e.pointerId);
  };

  const handleClose = () => {
    if (phase === "closing") return;
    playClick();
    setPhase("closing");
    setTimeout(() => onClose?.(), 250); // matches CSS duration
  };

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && handleClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <div
      className={`window ${phase}`}
      style={{ left: position.x, top: position.y, zIndex, width }}
      onMouseDown={onFocus}
      role="dialog"
      aria-label={title}
    >
      <div
        className="window-header"
        onPointerDown={startDrag}
        onPointerMove={onMove}
        onPointerUp={endDrag}
      >
        <h2 className="window-title">{title}</h2>
        <button
          className="window-close"
          data-no-drag
          onClick={handleClose}
          aria-label={`Close ${title}`}
        >
          [×]
        </button>
      </div>
      <div className="window-content">{children}</div>
    </div>
  );
};