import { useMemo, useCallback } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faInfoCircle,
  faLink,
  faFolder,
  faSun,
  faMoon,
  faComments,
  faVolumeHigh,
  faVolumeMute
} from "@fortawesome/free-solid-svg-icons";
import Wavify from "react-wavify";
import "./Directory.css";
import "@fontsource-variable/roboto";

function IconButton({ onClick, icon, label }) {
  // stable handler avoids needless re-renders
  const handle = useCallback(onClick, [onClick]);
  return (
    <button
      className="icon-btn"
      onClick={handle}
      aria-label={label}
      title={label}
    >
      <FontAwesomeIcon icon={icon} />
      <span>{label}</span>
    </button>
  );
}

export default function Directory({ darkMode, toggleDarkMode, soundOn, toggleSoundOn, openWindow }) {
  // respect reduced motion
  const prefersReducedMotion = useMemo(
    () => window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ?? false,
    []
  );

  const open = useCallback((key) => () => openWindow(key), [openWindow]);

    // wave colors: match the new theme
  const waveColorBack = darkMode ? "#6f61d6" : "#9be7de";   // softer
  const waveColorFront = darkMode ? "#5a4fca" : "#7fded3";


  return (
    <div className={`home ${darkMode ? "dark" : "light"}`}>
      {/* Waves - behind everything */}
      <Wavify
        className="waves-back"
        fill={waveColorBack}
        paused={prefersReducedMotion}
        options={{ height: 15, amplitude: 15, speed: 0.15, points: 4 }}
      />
      <Wavify
        className="waves-front"
        fill={waveColorFront}
        paused={prefersReducedMotion}
        options={{ height: 30, amplitude: 10, speed: 0.3, points: 9 }}
      />

      {/* Top left toggles */}
      <div className="top-left">
        <button
          onClick={toggleDarkMode}
          aria-label={darkMode ? "Switch to light mode" : "Switch to dark mode"}
          aria-pressed={darkMode}
          title={darkMode ? "Light mode" : "Dark mode"}
          className="mode-toggle"
        >
          <FontAwesomeIcon icon={darkMode ? faSun : faMoon} />
        </button>
        <button
          onClick={toggleSoundOn}
          aria-label={soundOn ? "Unmute" : "Mute"}
          aria-pressed={soundOn}
          title={soundOn ? "Muted" : "Unmuted"}
          className="mode-toggle"
        >
          <FontAwesomeIcon icon={soundOn ? faVolumeHigh : faVolumeMute} />
        </button>
      </div>


      <div className="card">
        <div className="card-header">system://home</div>

        <div className="card-content">
          {/* headline */}
          <h1>
            <span>hey, i'm</span>{" "}
            <span className="name">emma</span>
          </h1>
          <p style={{ marginTop: 6, color: "var(--muted)" }}>
            student developer
          </p>

          <div className="icon-buttons">
            <IconButton onClick={open("about")}    icon={faInfoCircle} label="about me" />
            <IconButton onClick={open("links")}    icon={faLink}       label="links" />
            <IconButton onClick={open("projects")} icon={faFolder}     label="projects" />
            {/* <IconButton onClick={open("chat")}     icon={faComments}   label="chat" /> */}
          </div>
        </div>
      </div>
    </div>
  );
}
