import { useState, useEffect, useMemo, useLayoutEffect, useRef, useCallback } from "react";
import { Box } from "@mui/material";
import "./Maze.css";
import useSound from "use-sound";
import clickSound from "../assets/click.mp3";
import jingleSound from "../assets/toggle.mp3";
import "@fontsource-variable/roboto";

/* FontAwesome like in Directory/Home */
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faSun, faMoon, faVolumeHigh, faVolumeMute, faFlagCheckered } from "@fortawesome/free-solid-svg-icons";

const DIRS = [
	[1, 0],
	[-1, 0],
	[0, 1],
	[0, -1],
];

const makeId = (x, y) => `${x},${y}`;

export default function Maze() {
	const SIZE = 21;

	const [soundOn, setSoundOn] = useState(true);
	const [darkMode, setDarkMode] = useState(false);
	const [activeTiles, setActiveTiles] = useState(() => new Set());
	const [startId, setStartId] = useState("0,0");
	const [endId, setEndId] = useState("2,2");
	const [pathIds, setPathIds] = useState([]);
	const [visitedIds, setVisitedIds] = useState(new Set());
	const [frontierIds, setFrontierIds] = useState(new Set());
	const [animating, setAnimating] = useState(false);
	const [speedMs] = useState(1);

	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

	const [playClick] = useSound(clickSound, { volume: soundOn ? 0.15 : 0 });
	const [playJingle] = useSound(jingleSound, { volume: soundOn ? 0.3 : 0 });
	const lastRightClickTime = useRef(0);
	const DOUBLE_MS = 300;

	const lastSoundAt = useRef(0);
	const playTick = () => {
		const now = performance.now();
		if (now - lastSoundAt.current > 60) {
			playClick();
			lastSoundAt.current = now;
		}
	};

	const idToGrid = (id, size) => {
		const [x, y] = id.split(",").map(Number);
		const c = Math.floor(size / 2);
		return { col: x + c, row: c - y };
	};

	const animateBFS = async (activeTiles, allTiles, start, end) => {
		if (animating) return;
		setAnimating(true);
		setPathIds([]);
		setVisitedIds(new Set());
		setFrontierIds(new Set());

		const passable = new Set(
			allTiles.filter((t) => !activeTiles.has(t.id)).map((t) => t.id)
		);
		passable.add(start);
		passable.add(end);

		if (!passable.has(start) || !passable.has(end)) {
			setAnimating(false);
			return;
		}

		const q = [start];
		const visited = new Set([start]);
		const frontier = new Set([start]);
		const parent = new Map();

		setFrontierIds(new Set(frontier));

		let found = false;
		while (q.length) {
			const cur = q.shift();
			frontier.delete(cur);
			setFrontierIds(new Set(frontier));

			visited.add(cur);
			setVisitedIds(new Set(visited));
			await sleep(speedMs);

			if (cur === end) {
				found = true;
				break;
			}

			const [cx, cy] = cur.split(",").map(Number);
			for (const [dx, dy] of DIRS) {
				const nx = cx + dx;
				const ny = cy + dy;
				const nid = makeId(nx, ny);
				if (!passable.has(nid)) continue;
				if (visited.has(nid)) continue;
				if (parent.has(nid)) continue;

				parent.set(nid, cur);
				q.push(nid);
				frontier.add(nid);
				setFrontierIds(new Set(frontier));
				await sleep(speedMs);
			}
		}

		if (found) {
			const rev = [];
			for (let cur = end; cur != null; cur = parent.get(cur)) {
				rev.push(cur);
				if (cur === start) break;
			}
			rev.reverse();

			const drawn = [];
			for (const id of rev) {
				drawn.push(id);
				setPathIds([...drawn]);
				await sleep(Math.max(25, speedMs - 10));
			}
		}

		setAnimating(false);
	};

	const pathPoints = useMemo(() => {
		if (!pathIds || pathIds.length < 2) return "";
		return pathIds
			.map((id) => {
				const { col, row } = idToGrid(id, SIZE);
				return `${col + 0.5},${row + 0.5}`;
			})
			.join(" ");
	}, [pathIds, SIZE]);

	useLayoutEffect(() => {
		document.body.classList.toggle("light", !darkMode);
	}, [darkMode]);

	const toggleDarkMode = useCallback(() => {
		setDarkMode((p) => !p);
		playJingle();
	}, [playJingle]);

	const toggleSound = useCallback(() => {
		setSoundOn((p) => !p);
	}, []);

	const handleRightPointer = (id, e) => {
		e.preventDefault();
		const now = performance.now();
		if (now - lastRightClickTime.current < DOUBLE_MS) {
			setEndId(id);
			playTick?.();
		} else {
			setStartId(id);
			playTick?.();
		}
		lastRightClickTime.current = now;
	};

	const tiles = useMemo(() => {
		const c = Math.floor(SIZE / 2);
		const arr = [];
		for (let row = 0; row < SIZE; row++) {
			for (let col = 0; col < SIZE; col++) {
				const x = col - c;
				const y = c - row;
				arr.push({ id: `${x},${y}`, x, y });
			}
		}
		return arr;
	}, [SIZE]);

	const isDraggingRef = useRef(false);
	const dragModeRef = useRef(null);

	const startDrag = (id) => {
		isDraggingRef.current = true;
		setActiveTiles((prev) => {
			const next = new Set(prev);
			const has = next.has(id);
			dragModeRef.current = has ? "delete" : "add";
			has ? next.delete(id) : next.add(id);
			return next;
		});
		playTick();
	};

	const enterTileWhileDragging = (id) => {
		if (!isDraggingRef.current || !dragModeRef.current) return;
		setActiveTiles((prev) => {
			const next = new Set(prev);
			const has = next.has(id);
			if (dragModeRef.current === "add" && !has) {
				next.add(id);
				playTick();
			}
			if (dragModeRef.current === "delete" && has) {
				next.delete(id);
				playTick();
			}
			return next;
		});
	};

	const endDrag = () => {
		isDraggingRef.current = false;
		dragModeRef.current = null;
	};

	useEffect(() => {
		const up = () => endDrag();
		const cancel = () => endDrag();
		window.addEventListener("pointerup", up, true);
		window.addEventListener("pointercancel", cancel, true);
		window.addEventListener("blur", cancel, true);
		return () => {
			window.removeEventListener("pointerup", up, true);
			window.removeEventListener("pointercancel", cancel, true);
			window.removeEventListener("blur", cancel, true);
		};
	}, []);

	useEffect(() => {
		setPathIds([]);
		setVisitedIds(new Set());
		setFrontierIds(new Set());
	}, [activeTiles, startId, endId]);

	const handleDone = async () => {
		await animateBFS(activeTiles, tiles, startId, endId);
	};

	return (
		<div className="maze-desktop">
			<div className="top-left">
				<button className="mode-toggle" onClick={toggleDarkMode} title="mode" aria-label="toggle theme">
					<FontAwesomeIcon icon={darkMode ? faSun : faMoon} />
				</button>
				<button className="mode-toggle" onClick={toggleSound} title="sound" aria-label="toggle sound">
					<FontAwesomeIcon icon={soundOn ? faVolumeHigh : faVolumeMute} />
				</button>
			</div>

			{darkMode && <div className="stars" />}

			{/* {soundOn && (
				<iframe
					className="lofi-player"
					src="https://www.youtube.com/embed/jfKfPfyJRdk?autoplay=1&loop=1&playlist=jfKfPfyJRdk"
					title="lofi beats"
					allow="autoplay"
					frameBorder="0"
				/>
			)}
 */}
			{/* Window shell */}
			<div className="maze-window" aria-label="Maze">
				<div className="maze-header">
					<span className="maze-title">system://maze</span>
				</div>

				<div className="maze-content">
					<div
						className="grid-wrap"
						style={{
							width: "min(80vmin, 90%)",
							aspectRatio: "1",
							margin: "0 auto",
							position: "relative",
							alignSelf: "center",
						}}
					>
						<Box
							className="grid"
							sx={{
								position: "absolute",
								inset: 0,
								display: "grid",
								gridTemplateColumns: `repeat(${SIZE}, 1fr)`,
								gridTemplateRows: `repeat(${SIZE}, 1fr)`,
								gap: "2px",
								userSelect: "none",
								touchAction: "none",
								cursor: "crosshair",
								alignSelf: "center",
								aspectRatio: "1",
							}}
						>
							{tiles.map((t) => {
								const isActive = activeTiles.has(t.id);
								const isInPath = pathIds.includes(t.id);
								const isFrontier = frontierIds.has(t.id);
								const isVisited = visitedIds.has(t.id);

								return (
									<Box
										key={t.id}
										role="button"
										tabIndex={0}
										aria-pressed={isActive}
										onPointerDown={(e) => {
											if (animating) return;
											if (e.button === 2) {
												handleRightPointer(t.id, e);
												return;
											}
											if (e.button !== 0) return;
											e.preventDefault();
											startDrag(t.id);
										}}
										onContextMenu={(e) => e.preventDefault()}
										onPointerEnter={(e) => {
											if (animating) return;
											if (e.buttons !== 1) return;
											enterTileWhileDragging(t.id);
										}}
										onPointerUp={(e) => {
											if (animating) return;
											e.preventDefault();
											endDrag();
										}}
										sx={{
											border: "1px solid",
											aspectRatio: "1",
											borderColor: "var(--tile-border)",
											borderRadius: 1,
											bgcolor:
												t.id === startId
													? "var(--start)"
													: t.id === endId
														? "var(--end)"
														: isInPath
															? "var(--path)"
															: isFrontier
																? "var(--frontier)"
																: isVisited
																	? "var(--visited)"
																	: isActive
																		? "var(--text)"
																		: "var(--bg)",
											transition:
												"background-color 0.12s ease, border-color 0.12s ease",
											"&:hover": {
												bgcolor:
													t.id === startId
														? "var(--start)"
														: t.id === endId
															? "var(--end)"
															: isActive
																? "var(--text)"
																: "var(--tile-hover)",
											},
											cursor: "crosshair",
										}}
									/>
								);
							})}
						</Box>

						<svg
							viewBox={`0 0 ${SIZE} ${SIZE}`}
							preserveAspectRatio="none"
							style={{
								position: "absolute",
								inset: 0,
								width: "100%",
								height: "100%",
								pointerEvents: "none",
							}}
						>
							<defs>
								<filter id="pathGlow" x="-50%" y="-50%" width="200%" height="200%">
									<feGaussianBlur in="SourceGraphic" stdDeviation="0.35" result="blur1" />
									<feGaussianBlur in="SourceGraphic" stdDeviation="0.8" result="blur2" />
									<feMerge>
										<feMergeNode in="blur1" />
										<feMergeNode in="blur2" />
										<feMergeNode in="SourceGraphic" />
									</feMerge>
								</filter>
							</defs>
							{pathPoints && (
								<polyline
									points={pathPoints}
									fill="none"
									stroke="#fff70f"
									strokeWidth={0.2}
									strokeLinecap="round"
									strokeLinejoin="round"
									opacity="1"
									filter="url(#pathGlow)"
								/>
							)}
						</svg>
					</div>
				</div>

				<div className="maze-footer">
					<button className="btn-cta" onClick={handleDone}>
						<FontAwesomeIcon icon={faFlagCheckered} style={{ marginRight: 8 }} />
						find shortest path
					</button>
				</div>
			</div>
		</div>
	);
}
