import { useState, useMemo, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import * as THREE from 'three';
import { compile } from 'mathjs';
import './Graph.css';
import useSound from "use-sound";
import clickSound from "../assets/click.mp3";
import jingleSound from "../assets/toggle.mp3";
import "@fontsource-variable/roboto";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faSun, faMoon, faVolumeHigh, faVolumeMute, faFlagCheckered } from "@fortawesome/free-solid-svg-icons";

const readVar = (name) => {
	const v = getComputedStyle(document.body).getPropertyValue(name).trim();
	return v || undefined;
};

function Axes({ range = 10 }) {
	const positionsX = [];
	const positionsY = [];
	const positionsZ = [];
	for (let i = -range; i <= range; i += (2 * range)) {
		positionsX.push(i, 0, 0);
		positionsY.push(0, i, 0);
		positionsZ.push(0, 0, i);
	}

	const geometryX = useMemo(() => {
		const g = new THREE.BufferGeometry();
		g.setAttribute('position', new THREE.Float32BufferAttribute(positionsX, 3));
		return g;
	}, [positionsX]);

	const geometryY = useMemo(() => {
		const g = new THREE.BufferGeometry();
		g.setAttribute('position', new THREE.Float32BufferAttribute(positionsY, 3));
		return g;
	}, [positionsY]);

	const geometryZ = useMemo(() => {
		const g = new THREE.BufferGeometry();
		g.setAttribute('position', new THREE.Float32BufferAttribute(positionsZ, 3));
		return g;
	}, [positionsZ]);

	return (
		<line>
			<line geometry={geometryX}>
				<lineBasicMaterial className="line" color={readVar('--text')} />
			</line>
			<line geometry={geometryY}>
				<lineBasicMaterial className="line" color={readVar('--text')} />
			</line>
			<line geometry={geometryZ}>
				<lineBasicMaterial className="line" color={readVar('--text')} />
			</line>
		</line>
	);
}

function ParametricGraph({ exprX, exprZ, exprY, steps = 500 }) {
	const [xFn, yFn, zFn] = useMemo(() => {
		try {
			const x = compile(exprX);
			const y = compile(exprY);
			const z = compile(exprZ);
			return [x, y, z];
		} catch (e) {
			console.error('Invalid math expression:', e);
			return [null, null, null];
		}
	}, [exprX, exprY, exprZ]);

	const positions = [];
	for (let i = 0; i <= 1; i += 1 / steps) {
		const scope = { i, PI: Math.PI, E: Math.E };
		try {
			const x = xFn.evaluate(scope);
			const y = yFn.evaluate(scope);
			const z = zFn.evaluate(scope);
			if ([x, y, z].some(v => isNaN(v))) continue;
			positions.push(x, y, z);
		} catch {
			continue;
		}
	}

	const geometry = useMemo(() => {
		const g = new THREE.BufferGeometry();
		g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
		return g;
	}, [positions]);

	return (
		<line geometry={geometry}>
			<lineBasicMaterial className="line" color={readVar('--accent')} />
		</line>
	);
}

export default function Graph() {
	const [soundOn, setSoundOn] = useState(true);
	const [darkMode, setDarkMode] = useState(false);

	const [playClick] = useSound(clickSound, { volume: soundOn ? 0.3 : 0 });
	const [playJingle] = useSound(jingleSound, { volume: soundOn ? 0.3 : 0 });

	useEffect(() => {
		const handleLinkClick = (e) => {
			const a = e.target.closest("a[href]");
			if (a && !a.hasAttribute("data-no-sound")) {
				playClick();
			}
		};
		document.addEventListener("click", handleLinkClick, true);
		return () => document.removeEventListener("click", handleLinkClick, true);
	}, [playClick]);

	const handleToggleDarkMode = () => {
		setDarkMode((prev) => !prev);
		playJingle();
	};

	const handleToggleSound = () => {
		setSoundOn((prev) => !prev);
	};

	useEffect(() => {
		document.body.classList.toggle("light", !darkMode);
	}, [darkMode]);

	const [exprX, setExprX] = useState('cos(2 * PI * i)');
	const [exprY, setExprY] = useState('sin(2 * PI * i)');
	const [exprZ, setExprZ] = useState('i');

	return (
		<div className="main">
			{/* {soundOn && (
				<iframe
					className="lofi-player"
					src="https://www.youtube.com/embed/jfKfPfyJRdk?autoplay=1&loop=1&playlist=jfKfPfyJRdk"
					title="lofi beats"
					allow="autoplay"
					frameBorder="0"
				></iframe>
			)} */}

			<div className="top-left">
				<button className="mode-toggle" onClick={handleToggleDarkMode} title="mode" aria-label="toggle theme">
					<FontAwesomeIcon icon={darkMode ? faSun : faMoon} />
				</button>
				<button className="mode-toggle" onClick={handleToggleSound} title="sound" aria-label="toggle sound">
					<FontAwesomeIcon icon={soundOn ? faVolumeHigh : faVolumeMute} />
				</button>
			</div>

			<div className="canvas-container">
				<Canvas camera={{ position: [5, 5, 5], fov: 60 }}>
					<ambientLight intensity={0.5} />
					<directionalLight position={[5, 10, 5]} />
					<Grid className="grid" args={[20, 20]} cellColor={readVar("--muted")} sectionColor={readVar("--muted")} />
					<OrbitControls />
					<ParametricGraph exprX={exprX} exprY={exprY} exprZ={exprZ} />
					<Axes />
				</Canvas>
			</div>

			<div className="sidebar">
				<div className="sidebar-header">
					<h2>Parametric Function</h2>
				</div>
				<label>
					x(i) =
					<input value={exprX} onChange={e => setExprX(e.target.value)} />
				</label>
				<label>
					y(i) =
					<input value={exprY} onChange={e => setExprY(e.target.value)} />
				</label>
				<label>
					z(i) =
					<input value={exprZ} onChange={e => setExprZ(e.target.value)} />
				</label>
			</div>
		</div>
	);
}